import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易要义卷一 * 下","description":"周易要义 - 周易要义卷一 * 下","frontmatter":{"title":"周易要义卷一 * 下","description":"周易要义 - 周易要义卷一 * 下"},"headers":[],"relativePath":"zh/classics/yaoyi/004.md","filePath":"zh/classics/yaoyi/004.md"}'),r={name:"zh/classics/yaoyi/004.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易要义卷一-下" tabindex="-1">周易要义卷一 * 下 <a class="header-anchor" href="#周易要义卷一-下" aria-label="Permalink to “周易要义卷一 * 下”">​</a></h1><p>钦定四库全书</p><p>宋魏了翁辑讼至履</p><p>䷅</p><p>坎下乾上。 讼：有孚，窒惕，中吉。窒谓窒塞也。能惕然后可以获中吉。讼，才用反，争也，言之于公也。郑云：「辩财曰讼。」离宫游魂卦。窒，张栗反，徐得悉反，又得失反。马作咥，云读为踬，犹止也。郑云：「咥，觉悔貌。」终凶，利见大人，不利涉大川。正义曰：「讼，有孚，窒惕，中吉」者，窒，塞也；惕，惧也。凡讼者，物有不合，情相乖争，而致其讼。凡讼之体，不可妄兴，必有信实，被物止塞而能惕惧，中道而止，乃得吉也。「终凶」者，讼不可长，若终竟讼事，虽复窒惕，亦有凶也。「利见大人」者，物既有讼，须大人决之，故「利见大人」也。「不利涉大川」者，以讼不可长，若以讼而往涉危难，必有祸患，故「不利涉大川」。</p><p>彖曰：讼，上刚下险，险而健，讼。正义曰：此释繇辞之义。「讼，上刚下险，险而健，讼」者，上刚即乾也，下险即坎也，犹人意怀险恶，性又刚健，所以讼也。「中乃吉」者，谓此讼事以中途而止，乃得吉也。前注云「可以获中吉」，谓获中止之吉。不闭其源，使讼不至者，若能谦虚退让，与物不竞，即此是闭塞讼之根源，使讼不至也。今不能如此，是不闭塞讼源，使讼得至也。</p><p>「虽每不枉，而讼至终竟」者，谓虽每诉讼，陈其道理，不有枉曲，而讼至终竟，此亦凶矣。</p><p>象曰：天与水违行，讼。君子以作事谋始。「听讼，吾犹人也，必也使无讼乎！」无讼在于谋始，谋始在于作制。契之不明，讼之所以生也。物有其分，职不相滥，争何由兴？正义曰：天道西转，水流东注，是天与水相违而行，象人彼此两相乖戾，故致讼也。不云「水与天违行」者，凡讼之所起，必刚健在先，以为讼始，故云「天与水违行」也。</p><p>九二，不克讼，归而逋其邑，人三百户，无眚。以刚处讼，不能下物，自下讼上，宜其不克。若能以惧，归窜其邑，乃可以免灾。邑过三百，非为窜也，窜而据强，灾未免也。象曰：「不克讼」，归逋窜也。自下讼上，患至掇也。正义曰：「不克讼」者，克，胜也；以刚处讼，不能下物，自下讼上，与五相敌，不胜其讼，言讼不得胜也。归而逋其邑者，讼既不胜，怖惧还归，逋窜其邑。若其邑强大，则大都偶国，非逋窜之道。「人三百户无眚」者，若其邑狭小，唯三百户乃可也。</p><p>三百户者，郑注礼记云：「小国下大夫之制。」又郑注周礼小司徒云：方十里为成，九百夫之地，沟渠、城郭、道路三分去其一，余六百夫。又以田有不易，有一易，有再易，定受田三百家。即此「三百户」者，一成之地也。郑注云：不易之地，岁种之；一易之地，休一岁乃种；再易之地，休二岁乃种。言至薄也。苟自藏隐，不敢与五相敌，则无灾眚。象曰「归逋窜」者，释归而逋邑，以讼之不胜，故退归逋窜也。「患至掇」者，掇犹拾掇也。自下讼上，悖逆之道，故祸患来至，若手自拾掇，甚言患必来也。故王肃云：「若手拾掇物然。」释注「以刚至，灾未免也」。正义曰：「若能以惧归窜其邑，乃可免灾」者，如此意，则经称「其邑」二字连上为句，「人三百户」合下为句。</p><p>六三，食旧德，贞厉，终吉。或从王事，无成。体夫柔弱，以顺于上，不为九二自下讼上，不见侵夺，保全其有，故得食其旧德而不失也。居争讼之时，处两刚之间，而皆近不相得，故曰「贞厉」。柔体不争，系应在上，众莫能倾，故曰「终吉」。上壮争胜，难可忤也，故或从王事，不敢成也。正义曰：「食旧德」者，六三以阴柔顺从上九，不为上九侵夺，故保全己之所有，故食其旧日之德禄位。「贞厉」者，贞，正也；厉，危也。象曰「从上吉」者，释所以「食旧德」，以顺从上九，故得其「吉，食旧德」也。</p><p>九五：「讼，元吉」。处得尊位，为讼之主，用其中正，以断枉直。中则不过，正则不邪，刚无所溺，公无所偏，故「讼，元吉」。</p><p>此卦之内，断狱讼之人，凡有二主。案上注云：「善听之主，其在二乎？」是二为主也。此注又云：「为讼之主，用其中正，以断枉直。」是五又为主也。一卦两主者，凡诸卦之内，如此者多矣。五是其卦尊位之主，余爻是其卦为义之主。犹若复卦，初九是复卦之主，「复」义在于初九也。六五亦居复之尊位，为复卦尊位之主。如此之例，非一卦也。所以然者，五居尊位，犹若天子总统万几，与万物为主。故诸卦皆五居尊位，诸爻则偏主一事，犹若六卿春官主礼，秋官主刑之类。偏主一事，则其余诸爻各主一事也。即六卿总归于天子，诸卦之爻，皆以九五为尊位也。若卦由五位，五又居尊，止为一主也，若比之九五之类是也。今此讼卦，二既为主，五又为主，皆有断狱之德。其五与二爻，其义同然也，故俱以为主也。</p><p>案上彖辞「刚来而得中」，今九五象辞云「讼，元吉，以中正」，可知彖辞「刚来得中」，非据九五。辅嗣必以为九二者，凡上下二象，在于下象者则称来。故贲卦云「柔来而文刚」，是离下艮上而称柔来。今此云「刚来而得中」，故知九二也。且凡云来者，皆据异类而来。九二在二阴之中，故称来。九五在外卦，又三爻俱阳，不得称来。若于爻辞之中，亦有从下卦向上卦称来也。故需上六「有不速之客三人来」，谓下卦三阳。然需上六阴爻，阳来诣之，亦是往非类而称来也。</p><p>上九，或锡之鞶带，终朝三褫之。处讼之极，以刚居上，讼而得胜者也。以讼受锡，荣何可保？故终朝之间，褫带者三也。锡，星历反，又星自反，赐也。鞶，步干反，马云：「大也。」徐云：「王肃作盘。」正义曰：「或锡之鞶带」者，上九以刚居上，是讼而得胜者也。以其因讼得胜，受此锡服，非德而受，亦不足可敬，故终朝之间，三被褫脱也。</p><p>䷆</p><p>坎下坤上 师。贞丈人，吉，无咎。丈人，严庄之称也。为师之正，丈人乃吉也。兴役动众无功，罪也，故吉乃无咎也。正义曰：「师，贞丈人吉，无咎」者，师，众也；贞，正也；丈人谓严庄尊重之人。言为师之正，唯得严庄丈人监临主领，乃得「吉无咎」。马云：「二千五百人为师。」坎宫归魂卦。贞丈人绝句。丈人，庄严之称。郑云：「能以法度长于人。」</p><p>贞之为正，其义已见于此。复云「贞正」者，欲见齐众必须以正，故训「贞」为正也。与下文为首引之势，故云「能以众正，可以王矣」。「刚中而应」者，「刚中」谓九二，而应谓六五。「行险而顺」者，行险谓下体坎也，而顺谓上体坤也。若刚中而无应，或有应而不刚中，或行险而不柔顺，皆不可行师得吉也。「以此毒天下而民从之，吉，又何咎矣」者，毒犹役也。若用此诸德使役天下之众，人必从之，以得其吉，又何无功而咎责乎？自「刚中」以下，释「丈人吉，无咎」也，言丈人能备此诸德也。</p><p>象曰地中至畜众正义曰：「君子以容民畜众」者，言君子法此师卦，容纳其民，畜养其众。「地中有水」，欲见地能包水，水又众大，是容民畜众之象。若其不然，或当云地在水上，或云「上地下水，或云水上有地」。今云「地中有水」，盖取容畜之义也。畜，敕六反，聚也；王肃许六反，养也。</p><p>初六，「师出以律，否臧，凶」，为师之始，齐师者也。齐众以律，失律则散，故师出以律。律不可失，失律而臧，何异于否？</p><p>失令有功，法所不赦，故「师出不以律，否臧皆凶」。否音鄙，恶也，注同。马、郑、王肃方友反。正义曰：「初六师出以律」者，律，法也。「否」谓破败，即是凶也，何须更云「否臧凶」者？本意所明，虽臧亦凶。象曰「失律凶」者，释「师出以律」之义。言所以必须以律者，以其失律则凶。反经之文，以明经义。</p><p>「失令有功，法所不赦」者，解「何异于否」之义。令则法律也。若失此法令，虽有功劳，军法所不容赦，故云「何异于否」。然阃外之事，将军所裁，临事制宜，不必皆依君命，何得有功，法所不赦者，凡为师之体，理非一端，量事制宜，随时进退。此则将军所制，随时施行。苟顺私情，故违君命，犯律触法，则事不可赦耳。</p><p>九二：在师中，吉，无咎。王三锡命。以刚居中而应于上，在师而得其中者也。承上之宠，为师之主，任大役重，无功则凶，故吉乃「无咎」也。行师得吉，莫善怀邦，邦怀众服，锡莫重焉，故乃得成命。正义曰：「在师中，吉」者，以刚居中而应于五，是「在师中，吉」也。象曰「承天宠」者，释「在师中，吉」之义也。正谓承受五之恩宠，故「中吉」也。「怀万邦也」者，以其有功，能招怀万邦，故被「王三锡命」也。观注之意，以「在师中」为句，其「吉」字属下。观象之文，「在师中，吉，承天宠」者，则以「吉」字属上。此「吉」之一字，上下兼该，故注文属下，象文属上。但象略其「无咎」之字，故「吉」属「师中」也。故「乃得成命」者，案曲礼云：「三赐不及车马，一命受爵，再命受服，三命受车马。」三赐三命而尊之得成，故「乃得成命」也。宠，如字，郑云：「光耀也。」王肃作「龙」，云：「宠也。」</p><p>六四，师左次，无咎。得位而无应，无应不可以行，得位则可以处，故左次之，而「无咎」也。行师之法，欲右背高，故左次之。象曰：「左次，无咎」，未失常也。虽不能有𫉬，足以不失其常也。正义曰：行师之法，欲右背高者，此兵法也。故汉书韩信云：「兵法欲右背山陵，前左水泽。」</p><p>庄氏云：「长子谓九二，德长于人；弟子谓六三，德劣于物。」今案：象辞云：「长子帅师，以中行也。」是九二居中也。弟子舆尸，使不当也。谓六三失位也。</p><p>上六：「大君」至「乱邦」也。正义曰：「大君有命」者，上六处师之极，是师之终竟也。「大君」谓天子也。言天子爵命此上六，若其功大，使之开国为诸侯；若其功小，使之承家为卿大夫。「小人勿用」者，言开国承家，须用君子，勿用小人也。象曰「大君有命，以正功也」者，正此上六之功也。</p><p>䷇</p><p>坤下坎上 比，毗志反，卦内并同。彖云：「辅也。」序卦云：「比，比也。」子夏传云：「地得水而柔，水得地而流，故曰比。」徐又补履反。坤宫归魂卦</p><p>彖曰：「比，吉也。」比，辅也，下顺从也。「原筮，元永贞，无咎」，以刚中也。处比之时，将原筮以求无咎，其惟元永贞乎？夫群党相比而不以「元永贞」，则凶邪之道也。若不遇其主，则虽永贞而犹未足免于咎也。使永贞而无咎者，其唯九五乎？正义曰：「比，吉也」者，释「亲比为善」，言相亲比而得吉也。「辅也」者，释「比」所以得吉，「比」者，人来相辅助也。「下顺从」者，在下之人顺从于上，是相辅助也，谓众阴顺从九五也。自此以上，释比名为吉之义。「原筮，元永贞，无咎，以刚中」者，释「原筮，元永贞，无咎」之义。所以得如此者，以九五刚而处中，故使「比」者皆得「原筮，元永贞，无咎」也。元，大也；永，长也。为已有大长贞正，乃能原筮相亲比之情，得久长而无咎。</p><p>六四，外比之，贞吉。外比于五，履得其位，比不失贤，处不失位，故「贞吉」也。象曰：外比于贤，以从上也。六四，外比之至从上也正义曰：六四上比于五，欲「外比」也。居得其位，比不失贤，所以「贞吉」。凡下体为内，上体为外，六四比五，故云「外比」也。象曰「外比于贤，以从上也」者，九五居中得位，故称「贤」也。五在四上，四往比之，是「以从上」也。</p><p>九五，显比。王用三驱，失前禽，邑人不诫，吉。为比之主，而有应在二，「显比」者也。比而显之，则所亲者狭矣。夫无私于物，唯贤是与，则去之与来，皆无失也。夫三驱之礼，禽逆来趣己则舍之，背己而走则射之，爱于来而恶于去也，故其所施，常「失前禽」也。以「显比」而居王位，用三驱之道者也，故曰「王用三驱，失前禽也」。用其中正，征讨有常，伐不加邑，动必讨叛，邑人无虞，故「不诫」也。虽不得乎大人之吉，是「显比」之吉也。此可以为上之使，非为上道也。</p><p>象曰：「显比」之吉，位正中也。舍逆取顺，「失前禽」也。「邑人不诫」，上使中也正义曰：所以「显比」得吉者，以所居之位正而且中，故云「显比之吉」。「舍逆取顺，失前禽也」者，禽逆来向己者，则舍之而不害；禽顺去背己而走者，则射而取之，是「失前禽」也。「邑人不诫，上使中」者，释「邑人不诫」之义。所以己邑之人不须防诫，正由在上九五之使，得其中正之人，伐不加邑，动必讨叛，不横加无罪，正由在上使中也。「中」谓九五也。此九五虽不得为王者之身，堪为王者之使，以居中位，故云「上使中」也。</p><p>上六：「比之无首，凶。」无首，后也。处卦之终，是后夫也。亲道已成，无所与终，为时所弃，宜其凶也。</p><p>䷈</p><p>乾下巽上 小畜，亨。不能畜大，止健，刚志故行，是以亨。畜，本又作蓄，同，敕六反，积也，聚也。卦内皆同，郑许六反，养也。巽宫一世卦。正义曰：「小畜亨」者，但小有所畜，唯畜九三而已。初九、九二犹刚健得行，是以刚志上得亨通，故云「小畜，亨」也。若大畜，乾在于下，艮在于上，艮是阳卦，又能止物，能止此乾之刚健，所畜者大，故称「大畜」。此卦则巽在于上，乾在于下，巽是阴柔，性又和顺，不能止畜在下之乾，唯能畜止九三，所畜狭小，故名「小畜」。「密云不雨」者，若阳之上升，阴能畜止，两气相薄，则为雨也。今唯能畜止九三，其气被畜，但为「密云」。初九、九二犹自上通，所以不能为雨也。「自我西郊」者，所聚密云，由在我之西郊，去我既远，润泽不能行也，但聚在西郊而已。</p><p>健而巽，刚中而志行，乃亨。「密云不雨」，尚往也。「自我西郊」，施未行也。小畜之「𫝑」，足作「密云」，乃「自我西郊」，未足以为雨也。何由知未能为雨？夫能为雨者，阳上薄阴，阴能固之，然后烝而为雨。今不能制初九之「复自道」，固九二之「牵复」，九三更以不能复为劣也。下方尚往，施岂得行？故密云而不能为雨，尚往故也。何以明之？夫阴能固之，然后乃雨。今上九独能固九三之路，故九三不可以进，而「舆说辐」也。能固其路而安于上，故得「既雨既处」。若四、五皆能若上九之善畜，则能雨明矣。故举一卦而论之，能为小畜密云而已。阴苟不足以固阳，则虽复至盛，「密云自我西郊」，故不能雨也。雨之未下，即施之未行。</p><p>彖全论一卦之体，故曰「密云不雨」；象各言一爻之德，故曰「既雨既处」也。正义曰：「九三更以不能复为劣」者，初九既得「复道」，九二可「牵」以「𫉬复」，皆得刚健上通，则是阴不能固阳，而九三劣弱，又不能自复，则是阳不薄阴，是以皆不雨也。且小畜之义，贵于上往，而九三不能自复，更为劣弱，故言「九三更不能复为劣」也。「能固其路而安于上」者，谓上九能闭固九三之道路，不被九三所陵，得安于上，所以「既雨既处」也。故举一卦而论之，能为小畜密云而巳者，此明卦之与爻其义别也。但卦总二象，明上体不能闭固下体，所以密云不能为雨。爻则止明一爻之事，上九能固九三，所以上九而有雨也。所以卦与爻其义异也。诸卦多然。若比卦云「比吉」，上六则云「比之无首，凶」也。复卦云「复亨」，上六云「迷复，凶」也。此皆卦之与爻义相违反，他皆仿此。</p><p>象曰：风行至文德。正义曰：「君子以懿文德」者，懿，美也，以于其时施未得行，喻君子之人，但修美文德，待时而发。风为号令，若风行天下，则施附于物，不得云施未行也。今风在天上，去物既远，无所施及，故曰「风行天上」。</p><p>凡大象，君子所取之义，或取二卦之象而法之者，若「地中有水，师」，「君子以容民畜众」，取卦象包容之义；若履卦</p><p>象云「上天下泽，履。君子以辨上下」，取上下尊卑之义。如此之类，皆取二象，君子法以为行也。或直取卦名，因其卦义所有，君子法之，须合卦义行事者，若讼卦云「君子以作事谋始」，防其所讼之源，不取「天与水违行」之象。若小畜「君子以懿文德」，不取「风行天上」之象。余皆仿此。</p><p>上九、既雨既处，尚德载，妇贞厉，月几望，君子征凶。处小畜之极，能畜者也。阳不𫉬亨，故「既雨」也。刚不能侵，故「既处」也。体「巽」处上，刚不敢犯，「尚德」者也。为阴之长，能畜刚健，德积载者也。妇制其夫，臣制其君，虽贞近危，故曰「妇贞厉」也。阴之盈盛，莫盛于此，故曰「月几望」也。满而又进，必失其道；阴疑于阳，必见战伐。虽复君子，以征必凶，故曰「君子征凶」。象曰：「既雨既处」，德积载也；「君子征凶」，有所疑也。夫处下可以征而无咎者，唯「泰」也则然。「坤」本体下，又顺而弱，不能敌刚，故可以全其类，征而吉也。自此以往，则其进各有难矣。</p><p>夫「巽」虽不能若「艮」之善畜，犹不肯为「坤」之顺从也。故可得少进，不可尽陵也。是以初九、九二，其复则可，至于九三，则「舆说辐」也。夫大畜者，畜之极也。畜而不已，畜极则通。是以其畜之盛，在于四、五，至于上九，道乃大行。小畜积极而后乃能畜，是以四、五可以进，而上九说征之辐</p><p>䷉</p><p>兑下乾上 履虎尾，不咥人，亨。正义曰：「履虎尾，不咥人，亨」者，履卦之义，以六三为主，六三以阴柔履践九二之刚，履危者也。犹如履虎尾为危之甚。「不咥人，亨」者，以六三在兑体，兑为和说而应乾刚，虽履其危而不见害，故得亨通。犹若履虎尾，不见咥啮于人。此假物之象以喻人事。彖曰：履，柔履刚也。说而应乎乾，是以「履虎尾，不咥人，亨」。凡彖者，言乎一卦之所以为主也。成卦之体在六三也。「履虎尾」者，言其危也。三为履主，以柔履刚，履危者也。履虎尾而不见咥者，说而应乎乾也。乾，刚正之德者也，不以说行夫佞邪，而以说应乎乾，宜其履虎尾，不见咥而亨。艮宫五世卦，</p><p>象曰：上天下泽，履。君子以辨上下，定民志。正义曰：「君子以辨上下、定民志」者，天尊在上，泽卑处下，君子法此履卦之象，以分辨上下尊卑，以定正民之志意，使尊卑有序也。但此履卦名含二义，若以爻言之，则在上履践于下，六三履九二也。若以二卦上下之象言之，则「履」，礼也，在下以礼承事于上。此象之所言，取上下二卦卑承尊之义，故云「上天下泽，履」。但易含万象，反复取义，不可定为一体故也。</p><p>六三眇能视，跛能履。履虎尾，咥人，凶。武人为于大君。居履之时，以阳处阳，犹曰不谦，而况以阴居阳，以柔乘刚者乎？故以此为明，眇目者也；以此为行，跛足者也；以此履危，见咥者也。志在刚健，不修所履，欲以陵武加人，「为于大君」，行未能免于凶，而志存于五，顽之甚也。</p><p>九四：「履虎尾，诉诉，终吉。」逼近至尊，以阳承阳，处多惧之地，故曰「履虎尾，诉诉」也。然以阳居阴，以谦为本，虽处危惧，终𫉬其志，故「终吉」也。诉，山草反。子夏传云：「恐惧貌。」何休注公羊传云：「惊愕也。」马本作虩，音许逆反，云：「恐惧也。」说文同。广雅云：「惧也。」</p><p>上九：「视履考祥，其旋元吉。」祸福之祥，生乎所履，处履之极，履道成矣，故可「视履」而「考祥」也。居极应说，高而不危，是其旋也。履道大成，故「元吉」。周易要义卷一下，</p>',48)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
